import { useEffect, useMemo, useState } from 'react';
import brandMark from '../brand-mark.svg';

const STORE = 'jibonguard-theme-choice';
const cx = (...values) => values.filter(Boolean).join(' ');

async function api(url, options = {}) {
  let response;
  try { response = await fetch(url, { credentials: 'same-origin', cache: 'no-store', ...options }); }
  catch (error) { if (error instanceof TypeError) throw new Error(`Cannot reach the JibonGuard API at ${location.origin}. Keep the Node server running and open this app from its port 8000 URL.`); throw error; }
  let data = {};
  try { data = await response.json(); } catch { data = { error: 'The server returned an unreadable response.' }; }
  if (!response.ok) throw Object.assign(new Error(data.error || 'Request failed.'), { status: response.status });
  return data;
}
async function post(url, values, method = 'POST') {
  const csrf = await api('/api/auth/csrf');
  return api(url, { method, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf.csrf_token }, body: JSON.stringify(values) });
}
const initials = name => String(name || 'JG').trim().split(/\s+/).slice(0, 2).map(part => part[0] || '').join('').toUpperCase() || 'JG';
const today = () => new Date().toISOString().slice(0, 10);
const currentTime = () => `${String(new Date().getHours()).padStart(2, '0')}:00`;

function Brand({ light = false }) {
  return <a className={cx('brand', light && 'brand-light')} href="/" aria-label="JibonGuard AI home"><img className="brand-mark" src={brandMark} alt=""/><span className="brand-copy"><strong>Jibon<span>Guard</span><em>AI</em></strong><small>HEAT SAFETY, MADE PERSONAL</small></span></a>;
}
function ThemeButton() {
  const [dark, setDark] = useState(() => document.documentElement.dataset.theme === 'dark');
  useEffect(() => { document.documentElement.dataset.theme = dark ? 'dark' : 'light'; localStorage.setItem(STORE, dark ? 'dark' : 'light'); }, [dark]);
  return <button className="theme-button" type="button" onClick={() => setDark(value => !value)} aria-label={`Switch to ${dark ? 'light' : 'dark'} mode`} title={`Switch to ${dark ? 'light' : 'dark'} mode`}><span aria-hidden="true">{dark ? '☀' : '☾'}</span>{dark ? 'Light mode' : 'Dark mode'}</button>;
}
function Header({ dashboard = false, user, onLogout }) {
  if (dashboard) return <header className="dash-top"><button className="mobile-menu" aria-label="Open menu" onClick={() => document.body.classList.toggle('menu-open')}>☰</button><a className="dash-top-brand" href="/dashboard.html"><img src={brandMark} alt=""/> JibonGuard <b>AI</b></a><div className="top-right"><ThemeButton /><a className="subtle-link" href="/account.html">Account</a><button className="subtle-link" onClick={onLogout}>Sign out</button><span className="top-avatar">{initials(user?.full_name)}</span></div></header>;
  return <header className="site-top"><Brand /><nav><a href="/#how">How it works</a><a href="/#features">Features</a><a href="/#pricing">Pricing</a></nav><div className="top-actions"><ThemeButton /><a className="quiet-link" href="/login.html">Log in</a><a className="button primary small" href="/signup.html">Create account <span>→</span></a></div></header>;
}

function Home() {
  const [demo, setDemo] = useState({ job: 'Construction worker', hours: 3 });
  const [sent, setSent] = useState(false);
  const risk = Math.min(95, Math.round(27 + demo.hours * 10 + (demo.job === 'Construction worker' ? 12 : demo.job === 'Farmer' ? 7 : 0)));
  const label = risk >= 70 ? 'High risk' : risk >= 48 ? 'Moderate risk' : 'Lower risk';
  return <><Header /><main>
    <section className="home-hero wrap"><div className="hero-content"><span className="eyebrow"><i /> BUILT FOR OUTDOOR WORKERS</span><h1>Safer workdays<br />start with <span>knowing.</span></h1><p>JibonGuard turns local weather, work intensity, and time outdoors into clear, personal heat-safety guidance for every shift.</p><div className="hero-actions"><a className="button primary" href="/signup.html">Protect your team <span>→</span></a><a className="quiet-link" href="#how">See how it works <span className="play">▶</span></a></div><div className="hero-proof"><span className="proof-icon">✳</span><span><strong>Made for Bangladesh’s workforce</strong><small>Designed for real outdoor workdays and basic phones.</small></span></div></div>
      <div className="hero-art" aria-label="JibonGuard sample heat safety dashboard"><div className="sun"></div><div className="figure"><i className="head"></i><i className="body"></i><i className="leg one"></i><i className="leg two"></i><i className="arm"></i></div><div className="float-card weather-card"><span>☀</span><div><small>FEELS LIKE</small><strong>38°C <em>Dhaka</em></strong></div></div><div className="float-card alert-card"><span className="alert-mark">!</span><div><small>SAFETY CHECK</small><strong>Shade break recommended</strong></div></div><div className="art-caption">Know the risk. Take the next step.</div></div>
    </section>
    <section className="trust-row"><span>ONE PLATFORM, MANY WORKDAYS</span><div><b>Construction</b><b>Agriculture</b><b>Transport</b><b>Community health</b></div></section>
    <section className="home-section soft" id="how"><div className="wrap"><div className="section-heading"><div><span className="kicker">HOW IT WORKS</span><h2>Clear guidance,<br />for every shift.</h2></div><p>Turn changing conditions into practical actions workers and supervisors can use right away.</p></div><div className="feature-grid"><article className="feature"><span>01</span><h3>Know local conditions</h3><p>Bring site weather and forecast details into one place.</p></article><article className="feature"><span>02</span><h3>Understand work exposure</h3><p>Factor in workload, time outside, and opportunities for breaks.</p></article><article className="feature"><span>03</span><h3>Act with confidence</h3><p>Help supervisors coordinate water, shade, and timely alerts.</p></article></div></div></section>
    <section className="home-section" id="features"><div className="wrap demo-layout"><div><span className="kicker">TRY A SAMPLE</span><h2>See how exposure<br />can change the risk.</h2><p className="body-copy">This simple illustration shows how the job and continuous work time affect a sample recommendation.</p><label className="field">Work type<select value={demo.job} onChange={event => setDemo({ ...demo, job: event.target.value })}><option>Construction worker</option><option>Farmer</option><option>Delivery rider</option></select></label><label className="field">Continuous outdoor work <strong>{demo.hours} hours</strong><input type="range" min="0" max="6" value={demo.hours} onChange={event => setDemo({ ...demo, hours: Number(event.target.value) })} /></label><small className="disclaimer">Illustrative example, not a medical assessment.</small></div><div className="risk-card"><div className="risk-top"><span>JIBONGUARD SAMPLE</span><span className="live-dot">LIVE DEMO</span></div><div className="risk-meter" style={{ '--risk': `${risk}%` }}><div><strong>{risk}</strong><small>/ 100</small></div></div><span className={cx('risk-label', label.startsWith('High') && 'risk-high')}>{label}</span><h3>{label === 'High risk' ? 'Take a shade break now.' : 'Plan a regular water break.'}</h3><p>Risk rises with heat exposure, heavier work, and time spent outdoors.</p><div className="risk-tags"><span>{demo.job}</span><span>{demo.hours}h outdoors</span><span>Dhaka · 38°C</span></div></div></div></section>
    <section className="home-section soft" id="pricing"><div className="wrap pricing-row"><div><span className="kicker">START WITH A PILOT</span><h2>Make a safer shift<br />part of the plan.</h2><p>Explore JibonGuard with your team and find a practical way to support workers.</p></div><a className="button primary" href="/signup.html">Create an organization account <span>→</span></a></div></section>
    <section className="home-section contact-section"><div className="wrap contact-row"><div><span className="kicker">LET’S TALK</span><h2>Every workday<br />deserves protection.</h2><p>Tell us a little about your organization and we’ll help you get started.</p><a href="mailto:hello@jibonguard.org" className="contact-email">hello@jibonguard.org</a></div><form className="contact-card" onSubmit={event => { event.preventDefault(); setSent(true); }}><strong>Request a demo</strong><label className="field">Your name<input required placeholder="Your name" /></label><label className="field">Work email<input required type="email" placeholder="you@company.com" /></label><button className="button primary" type="submit">{sent ? 'Thanks — we’ll be in touch' : 'Request a demo →'}</button></form></div></section>
  </main><footer className="site-footer"><div className="wrap"><Brand light /><span>© 2026 JibonGuard. Built with care in Bangladesh.</span></div></footer></>;
}

function Message({ message, tone = 'error' }) { return message ? <div className={`notice ${tone}`} role="status">{message}</div> : null; }
function AuthPage({ mode }) {
  const query = new URLSearchParams(location.search), flow = mode === 'login' && query.get('mode') ? query.get('mode') : mode;
  const [message, setMessage] = useState(''), [tone, setTone] = useState('error'), [busy, setBusy] = useState(false);
  const [devLink, setDevLink] = useState('');
  const heading = flow === 'signup' ? 'Create your account' : flow === 'forgot' ? 'Reset your password' : flow === 'reset' ? 'Choose a new password' : flow === 'verify' ? 'Check your email' : flow === 'resend' ? 'Send a new verification link' : 'Welcome back';
  async function submit(event) {
    event.preventDefault(); setMessage(''); setBusy(true); const form = event.currentTarget, values = Object.fromEntries(new FormData(form));
    try {
      if (flow === 'signup') { values.privacy_consent = new FormData(form).get('privacy_consent') === 'on'; const data = await post('/api/auth/signup', values); setTone('success'); setMessage(data.message); form.reset(); }
      else if (flow === 'login') { values.remember = new FormData(form).get('remember') === 'on'; values.next = query.get('next') || '/dashboard.html'; const data = await post('/api/auth/login', values); location.assign(data.next || '/dashboard.html'); }
      else if (flow === 'forgot') { const data = await post('/api/auth/forgot', values); setTone('success'); setMessage(data.message); setDevLink(data.development_action_url || ''); }
      else if (flow === 'reset') { if(values.password!==values.confirm_password) throw new Error('The passwords do not match.'); const data = await post('/api/auth/reset', {token:query.get('token')||'',password:values.password}); setTone('success'); setMessage(data.message); }
      else if (flow === 'resend') { const data = await post('/api/auth/resend-verification', values); setTone('success'); setMessage(data.message); setDevLink(data.development_action_url || ''); }
      else if (flow === 'verify') { const data = await post('/api/auth/verify', {token:query.get('token')||''}); setTone('success'); setMessage(data.message); }
    } catch (error) { setTone('error'); setMessage(error.message); }
    finally { setBusy(false); }
  }
  const links = flow === 'signup' ? <p className="auth-foot">Already registered? <a href="/login.html">Log in</a></p> : flow === 'login' ? <p className="auth-foot">New to JibonGuard? <a href="/signup.html">Create an organization account</a></p> : <p className="auth-foot"><a href="/login.html">← Return to log in</a></p>;
  return <><Header /><main className="auth-page"><aside className="auth-intro"><Brand /><span className="kicker">WORKER SAFETY, MADE PERSONAL</span><h1>Protect the people<br />behind the work.</h1><p>See local conditions, coordinate breaks, and reach outdoor workers with timely safety guidance.</p><ul><li>✓ Works for teams and worksites</li><li>✓ Practical weather and heat insights</li><li>✓ Built around worker consent</li></ul></aside><section className="auth-form-wrap"><a className="back-link" href="/">← Back to JibonGuard</a><span className="kicker">{flow === 'signup' ? 'ORGANIZATION SIGN UP' : flow === 'login' ? 'ORGANIZATION ACCESS' : 'ACCOUNT SECURITY'}</span><h2>{heading}</h2><p className="muted">{flow === 'signup' ? 'Set up your organization workspace.' : flow === 'login' ? 'Sign in to manage your organization and worksites.' : flow === 'forgot' ? 'We’ll send a one-time reset link if an account matches your email.' : flow === 'reset' ? 'Choose a unique passphrase with at least 12 characters.' : flow === 'resend' ? 'Enter the email address used for your account.' : 'We use one-time email links to protect account access.'}</p><Message message={message} tone={tone} />{devLink && <a className="dev-link" href={devLink}>Open the one-time link →</a>}
      {flow === 'verify' && query.get('token') ? <form className="form-stack" onSubmit={submit}><button className="button primary" disabled={busy}>{busy ? 'Checking…' : 'Verify email'}</button></form> : <form className="form-stack" onSubmit={submit}>
        {flow === 'signup' && <><label className="field">Your name<input required name="name" autoComplete="name" maxLength="120" /></label><label className="field">Organization name<input required name="organization" autoComplete="organization" maxLength="160" /></label><div className="form-two"><label className="field">Organization type<select required name="organization_type" defaultValue=""><option value="" disabled>Select type</option>{[['construction','Construction'],['factory','Factory'],['ngo','NGO'],['union','Union'],['garage','Garage / partner'],['farm','Farm / cooperative'],['government','Government'],['other','Other']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label className="field">Estimated workers<input name="estimated_workers" type="number" min="0" max="1000000" defaultValue="0" /></label></div><label className="field">Phone number<input required name="phone" type="tel" maxLength="24" /></label></>}
        {(flow === 'login'||flow === 'signup'||flow === 'forgot'||flow === 'resend')&&<label className="field">Email address<input required name="email" type="email" autoComplete="email" maxLength="254" /></label>}
        {(flow === 'login'||flow === 'signup'||flow === 'reset')&&<label className="field">{flow==='reset'?'New password':'Password'}<input required name="password" type="password" autoComplete={flow==='login'?'current-password':'new-password'} minLength={flow==='login'?undefined:12} maxLength="128" /></label>}
        {flow==='reset'&&<label className="field">Confirm new password<input required name="confirm_password" type="password" autoComplete="new-password" minLength="12" maxLength="128" /></label>}
        {flow==='signup'&&<label className="consent-check"><input required type="checkbox" name="privacy_consent" /><span>I accept the <a href="/privacy.html">Privacy Notice</a> and Terms. Worker alerts require each worker’s separate consent.</span></label>}
        {flow==='login'&&<div className="remember-row"><label><input type="checkbox" name="remember" /> Remember this device</label><a href="/login.html?mode=forgot">Forgot password?</a></div>}
        <button className="button primary full" type="submit" disabled={busy}>{busy?'Please wait…':flow==='signup'?'Create organization account':flow==='login'?'Log in securely':flow==='forgot'?'Send reset link':flow==='reset'?'Update password':'Send verification link'} <span>→</span></button>
      </form>}{links}</section></main></>;
}

function Dashboard() {
  const dashboardViews=['overview','workers','sites','breaks','alerts','reports'];
  const [user,setUser]=useState(null),[view,setView]=useState(()=>dashboardViews.includes(location.hash.slice(1))?location.hash.slice(1):'overview'),[workers,setWorkers]=useState([]),[sites,setSites]=useState([]),[breaks,setBreaks]=useState([]),[weather,setWeather]=useState({}),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[search,setSearch]=useState(''),[riskFilter,setRiskFilter]=useState('all'),[editingWorker,setEditingWorker]=useState(null),[editingSite,setEditingSite]=useState(null),[editingBreak,setEditingBreak]=useState(null),[workerFormOpen,setWorkerFormOpen]=useState(false),[siteFormOpen,setSiteFormOpen]=useState(false),[breakFormOpen,setBreakFormOpen]=useState(false),[chatOpen,setChatOpen]=useState(false),[chat,setChat]=useState([]),[prompt,setPrompt]=useState('');
  const [breakValues,setBreakValues]=useState({alert_type:'break',site_id:'',break_date:today(),break_time:currentTime(),duration_minutes:15,status:'logged'});
  async function refresh() {
    const [workerData,siteData,breakData]=await Promise.all([api('/api/workers'),api('/api/sites'),api('/api/breaks')]);
    setWorkers(workerData.workers);setSites(siteData.sites);setBreaks(breakData.breaks);return siteData.sites;
  }
  useEffect(()=>{let alive=true;(async()=>{let data;try{data=await api('/api/auth/me');}catch{if(alive)location.assign(`/login.html?next=${encodeURIComponent(`/dashboard.html#${view}`)}`);return;}if(!alive)return;setUser(data.user);try{await refresh();}catch(error){if(alive)notify(`Dashboard data could not be loaded: ${error.message}`);}})();return()=>{alive=false;};},[]);
  useEffect(()=>{history.replaceState(null,'',`${location.pathname}${location.search}#${view}`);},[view]);
  useEffect(()=>{if(sites.length&&!breakValues.site_id)setBreakValues(v=>({...v,site_id:sites[0].id}));},[sites]);
  function notify(text){setNotice(text);window.clearTimeout(notify.timer);notify.timer=window.setTimeout(()=>setNotice(''),4500);}
  async function loadWeather(site){try{const result=await api(`/api/sites/${encodeURIComponent(site.id)}/weather`);setWeather(v=>({...v,[site.id]:result.weather}));}catch(error){notify(error.message);}}
  async function logout(){try{await post('/api/auth/logout',{});location.assign('/');}catch(error){notify(error.message);}}
  async function saveWorker(event){event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form));setBusy(true);try{const url=editingWorker?`/api/workers?id=${encodeURIComponent(editingWorker.id)}`:'/api/workers';await post(url,values,editingWorker?'PUT':'POST');await refresh();if(!editingWorker)setWorkerFormOpen(false);setEditingWorker(null);form.reset();notify(editingWorker?'Worker updated.':'Worker added.');}catch(error){notify(error.message);}finally{setBusy(false);}}
  async function removeWorker(worker){if(!confirm(`Remove ${worker.name} from your worker list? This cannot be undone.`))return;try{await post(`/api/workers?id=${encodeURIComponent(worker.id)}`,{},'DELETE');await refresh();notify('Worker removed.');}catch(error){notify(error.message);}}
  async function consent(worker){if(!worker.consent_at&&!confirm(`Confirm ${worker.name} received the privacy notice and explicitly agreed to receive safety alerts?`))return;const action=worker.consent_at?'withdrawn':'consented';try{await post('/api/workers/consent',{worker_id:worker.id,action,method:action==='consented'?'verbal':'',worker_agreed:action==='consented',note:action==='consented'?'Verbal agreement confirmed by organization admin.':'Consent withdrawn by organization admin.'});await refresh();notify(action==='consented'?'Consent recorded.':'Consent withdrawn.');}catch(error){notify(error.message);}}
  async function importCsv(event){const file=event.target.files?.[0];if(!file)return;try{const lines=(await file.text()).split(/\r?\n/).filter(Boolean);const parse=line=>line.split(',').map(item=>item.trim().replace(/^"|"$/g,''));const headers=parse(lines.shift()).map(x=>x.toLowerCase().replace(/\s+/g,'_'));const rows=lines.map(line=>Object.fromEntries(parse(line).map((value,i)=>[headers[i],value]))).map(row=>({name:row.name,phone:row.phone,site:row.site,job_type:row.job_type||row.role,workload:row.workload||'Standard'}));const result=await post('/api/workers/import',{workers:rows});await refresh();notify(`${result.imported} workers imported. Consent is pending.`);}catch(error){notify(error.message);}finally{event.target.value='';}}
  async function saveSite(event){event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form));setBusy(true);try{const result=await post(editingSite?`/api/sites?id=${encodeURIComponent(editingSite.id)}`:'/api/sites',values,editingSite?'PUT':'POST');await refresh();setEditingSite(null);setSiteFormOpen(false);form.reset();notify('Worksite saved.');if(result.site)await loadWeather(result.site);}catch(error){notify(error.message);}finally{setBusy(false);}}
  async function deleteSite(site){if(!confirm(`Delete ${site.name}? Sites with assigned workers cannot be deleted.`))return;try{await post(`/api/sites?id=${encodeURIComponent(site.id)}`,{},'DELETE');await refresh();notify('Worksite removed.');}catch(error){notify(error.message);}}
  function openNewBreak(){setEditingBreak(null);setBreakValues({alert_type:'break',site_id:sites[0]?.id||'',break_date:today(),break_time:currentTime(),duration_minutes:15,status:'logged'});setBreakFormOpen(true);}
  function openBreakEditor(item){const site=sites.find(entry=>entry.name===item.site);setEditingBreak(item);setBreakValues({alert_type:item.alert_type||'break',site_id:site?.id||'',break_date:item.break_date,break_time:item.break_time,duration_minutes:item.duration_minutes,status:item.status||'logged'});setBreakFormOpen(true);}
  async function createBreak(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const values={...breakValues,...Object.fromEntries(new FormData(form))};values.duration_minutes=Number(values.duration_minutes);setBusy(true);try{const endpoint=editingBreak?`/api/breaks?id=${encodeURIComponent(editingBreak.id)}`:'/api/breaks';const result=await post(endpoint,values,editingBreak?'PUT':'POST');await refresh();setBreakFormOpen(false);setEditingBreak(null);notify(result.sms?.message||(editingBreak?'Break log updated.':'Break log saved.'));}catch(error){notify(error.message);}finally{setBusy(false);}}
  async function schedule(){setBusy(true);try{const result=await post('/api/breaks/ai-schedule',{});await refresh();notify(result.message);}catch(error){notify(error.message);}finally{setBusy(false);}}
  async function sendChat(event){event.preventDefault();const text=prompt.trim();if(!text||busy)return;const history=[...chat,{role:'user',text}];setChat(history);setPrompt('');setBusy(true);try{const result=await post('/api/ai/chat',{messages:history});setChat([...history,{role:'model',text:result.reply}]);}catch(error){setChat([...history,{role:'model',text:`Sorry, I couldn't get a response: ${error.message}`}]);}finally{setBusy(false);}}
  const visibleWorkers=useMemo(()=>workers.filter(worker=>(!search||`${worker.name} ${worker.site} ${worker.job_type}`.toLowerCase().includes(search.toLowerCase()))&&(riskFilter==='all'||(riskFilter==='consent'?(worker.consent_at||worker.consent_status==='withdrawn'):worker.risk_level===riskFilter))),[workers,search,riskFilter]);
  if(!user)return <div className="loading"><Brand /><span>Opening your workspace…</span></div>;
  const nav=[['overview','Overview','◫'],['workers','Workers','♙'],['sites','Sites','⌖'],['breaks','Break schedule','◷'],['alerts','Alerts','◎'],['reports','Reports','▧']];
  return <div className="dashboard-app"><aside className="sidebar"><a className="side-brand" href="/"><img src={brandMark} alt=""/> JibonGuard <b>AI</b></a><div className="org-card"><span className="org-avatar">{initials(user.organization_name).slice(0,1)}</span><div><strong>{user.organization_name}</strong><small>Organization admin</small></div></div><span className="nav-caption">WORKSPACE</span><nav className="side-nav">{nav.map(([key,label,icon])=><button key={key} className={cx(view===key&&'active')} onClick={()=>setView(key)}><span>{icon}</span>{label}{key==='workers'&&<em>{workers.length}</em>}</button>)}</nav><div className="sidebar-bottom"><div className="support-card"><strong>Need a hand?</strong><small>Our safety team is here to help.</small><a href="mailto:hello@jibonguard.org">Contact support →</a></div><div className="profile"><span>{initials(user.full_name)}</span><div><strong>{user.full_name}</strong><small>{user.email}</small></div></div></div></aside>
    <main className="dash-main"><Header dashboard user={user} onLogout={logout}/><div className="dash-content"><div className="dash-title"><div><span className="kicker">WORKER SAFETY WORKSPACE</span><h1>{nav.find(item=>item[0]===view)?.[1]||'Overview'}</h1><p>Manage workers, worksites, consent, and break safety.</p></div><div className="dash-title-actions"><button className="button secondary" onClick={()=>{setEditingSite(null);setSiteFormOpen(true);setView('sites');}}>＋ Add a worksite</button><button className="button primary" onClick={()=>{setWorkerFormOpen(true);setView('workers');}}>＋ Add worker</button></div></div>
      {notice&&<Message message={notice} tone="success"/>}
      {view==='overview'&&<><div className="metric-grid"><Metric title="WORKERS" value={workers.length} sub="In your organization" color="green"/><Metric title="ACTIVE CONSENT" value={workers.filter(w=>w.consent_at).length} sub="Consent recorded" color="blue"/><Metric title="WORKSITES" value={sites.length} sub="Saved locations" color="purple"/><Metric title="BREAK LOGS" value={breaks.length} sub="Scheduled and completed" color="orange"/></div><div className="dash-grid"><section className="panel"><div className="panel-head"><div><h2>Team at a glance</h2><p>Consent and worksite coverage</p></div><button className="text-button" onClick={()=>setView('workers')}>View workers →</button></div>{workers.length?<div className="overview-list">{workers.slice(0,6).map(worker=><div className="overview-worker" key={worker.id}><span className="mini-avatar">{initials(worker.name)}</span><strong>{worker.name}</strong><span>{worker.site}</span><Badge tone={worker.consent_at?'good':'pending'}>{worker.consent_at?'Consented':'Pending'}</Badge></div>)}</div>:<Empty title="Add your first worker" body="Create a worker record and assign it to one of your worksites." action="Add worker" onClick={()=>setView('workers')}/>}</section><section className="panel"><div className="panel-head"><div><h2>Upcoming safety actions</h2><p>Recent break plans and alerts</p></div><button className="text-button" onClick={()=>setView('breaks')}>Open schedule →</button></div>{breaks.length?<div className="simple-list">{breaks.slice(0,5).map(item=><div key={item.id}><span className="list-dot"/><div><strong>{item.title}</strong><small>{item.site} · {item.break_date} at {item.break_time}</small></div><Badge tone={item.source==='ai'?'ai':'neutral'}>{item.source==='ai'?'AI':'Manual'}</Badge></div>)}</div>:<Empty title="No breaks logged yet" body="Log a break or ask the assistant for a weather-based suggestion." action="Create a break" onClick={()=>setView('breaks')}/>}</section></div><section className="panel safety-callout"><span className="callout-icon">✳</span><div><strong>Practical guidance for changing weather</strong><p>Add site coordinates to view current conditions and get weather-informed recommendations.</p></div><button className="button secondary" onClick={()=>setView('sites')}>Manage worksites</button></section></>}
      {view==='workers'&&<><div className={cx('dash-grid worker-layout',workerFormOpen&&'form-open')}><section className="panel"><div className="panel-head"><div><h2>Worker directory</h2><p>Consent is required before alerts are sent.</p></div><div className="worker-list-actions"><button className="button secondary small" onClick={()=>setWorkerFormOpen(open=>!open)}>{workerFormOpen?'Close form':'Add worker'}</button><label className="upload-button">Import CSV<input type="file" accept=".csv,text/csv" onChange={importCsv}/></label></div></div><div className="table-tools"><input aria-label="Search workers" placeholder="Search name, role, site..." value={search} onChange={e=>setSearch(e.target.value)}/><select value={riskFilter} onChange={e=>setRiskFilter(e.target.value)}><option value="all">All workers</option><option value="consent">Consent status</option></select></div><div className="table-scroll"><table><thead><tr><th>WORKER</th><th>WORKSITE</th><th>ROLE</th><th>CONSENT</th><th>ACTIONS</th></tr></thead><tbody>{visibleWorkers.map(worker=><tr key={worker.id}><td><span className="table-avatar">{initials(worker.name)}</span><strong>{worker.name}</strong></td><td>{worker.site}</td><td>{worker.job_type}<small>{worker.workload} workload</small></td><td><Badge tone={worker.consent_at?'good':'pending'}>{worker.consent_at?'Consented':worker.consent_status==='withdrawn'?'Withdrawn':'Pending'}</Badge></td><td><button className="tiny-action" onClick={()=>setEditingWorker(worker)}>Edit</button><button className="tiny-action" onClick={()=>consent(worker)}>{worker.consent_at?'Withdraw':'Consent'}</button><button className="tiny-action danger" onClick={()=>removeWorker(worker)}>Remove</button></td></tr>)}</tbody></table>{!visibleWorkers.length&&<p className="empty-inline">No workers match this view.</p>}</div></section>{workerFormOpen&&<section className="panel form-panel"><div className="panel-head"><div><span className="kicker">NEW WORKER</span><h2>Add a worker</h2><p>Enter worker details and assign a worksite.</p></div><button type="button" className="text-button" onClick={()=>setWorkerFormOpen(false)}>Close</button></div><form className="form-stack" key="new-worker" onSubmit={saveWorker}><label className="field">Full name<input name="name" required maxLength="120"/></label><label className="field">Phone number<input name="phone" required type="tel"/></label><label className="field">Worksite<select name="site_id" required defaultValue=""><option value="">Choose a saved worksite</option>{sites.map(site=><option key={site.id} value={site.id}>{site.name}</option>)}</select></label><label className="field">Job type<input name="job_type" required maxLength="120"/></label><label className="field">Workload<select name="workload" defaultValue="Standard"><option>Light</option><option>Standard</option><option>Heavy</option></select></label>{!sites.length&&<p className="form-hint">Create a worksite before adding workers.</p>}<button className="button primary full" disabled={busy||!sites.length}>{busy?'Saving...':'Add worker'}</button></form></section>}</div>{editingWorker&&<div className="worker-editor-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)setEditingWorker(null);}}><section className="worker-editor panel" role="dialog" aria-modal="true" aria-labelledby="worker-editor-title"><div className="panel-head"><div><span className="kicker">WORKER RECORD</span><h2 id="worker-editor-title">Edit {editingWorker.name}</h2><p>Update this worker contact and work details.</p></div><button type="button" className="editor-close" aria-label="Close worker editor" onClick={()=>setEditingWorker(null)}>{String.fromCharCode(215)}</button></div><form className="form-stack" key={editingWorker.id} onSubmit={saveWorker}><label className="field">Full name<input name="name" required maxLength="120" defaultValue={editingWorker.name}/></label><label className="field">Phone number<input name="phone" required type="tel" defaultValue={editingWorker.phone}/></label><label className="field">Worksite<select name="site_id" required defaultValue={editingWorker.site_id||''}><option value="">Choose a saved worksite</option>{sites.map(site=><option key={site.id} value={site.id}>{site.name}</option>)}</select></label><label className="field">Job type<input name="job_type" required maxLength="120" defaultValue={editingWorker.job_type}/></label><label className="field">Workload<select name="workload" defaultValue={editingWorker.workload||'Standard'}><option>Light</option><option>Standard</option><option>Heavy</option></select></label><div className="editor-actions"><button type="button" className="button secondary" onClick={()=>setEditingWorker(null)}>Cancel</button><button className="button primary" disabled={busy}>{busy?'Saving...':'Save changes'}</button></div></form></section></div>}</>}
      {view==='sites'&&<div className="site-layout">
        {!siteFormOpen&&!editingSite&&<section className="panel"><div className="panel-head"><div><h2>Worksites</h2><p>Coordinates enable local weather and AI recommendations.</p></div><div className="site-list-actions"><span className="badge neutral">{sites.length} saved</span><button className="button primary" onClick={()=>{setEditingSite(null);setSiteFormOpen(true);}}>Add worksite</button></div></div>{sites.map(site=><article className="site-card" key={site.id}><div className="site-heading"><span className="site-pin">?</span><div><strong>{site.name}</strong><small>{site.address||'Address not set'}</small></div><div className="site-actions"><button className="tiny-action" onClick={()=>{setEditingSite(site);setSiteFormOpen(true);}}>Edit</button><button className="tiny-action danger" onClick={()=>deleteSite(site)}>Delete</button></div></div>{weather[site.id]?<div className="site-weather"><strong>{weather[site.id].current.temperature}?C ? {weather[site.id].current.summary}</strong><span>Feels like {weather[site.id].current.feels_like}?C ? Humidity {weather[site.id].current.humidity}%</span><small>{weather[site.id].hourly.data.slice(0,5).map(h=>`${h.label}: ${h.temperature}?`).join('  ?  ')}</small></div>:<div className="site-weather empty-weather">{site.latitude==null?'Add coordinates to enable weather.':'Weather not loaded yet.'}</div>}<div className="site-card-footer"><span>{workers.filter(w=>w.site_id===site.id).length} assigned workers</span><button className="text-button" onClick={()=>loadWeather(site)}>Refresh weather ?</button></div></article>)}{!sites.length&&<Empty title="No worksites yet" body="Save your first worksite to organize teams and get local weather."/>}</section>}
        {(siteFormOpen||editingSite)&&<section className="panel form-panel site-form-page"><div className="panel-head"><div><span className="kicker">{editingSite?'EDIT WORKSITE':'NEW WORKSITE'}</span><h2>{editingSite?'Edit worksite':'Add a worksite'}</h2><p>Search a place or enter its coordinates. The map updates with your selection.</p></div><button type="button" className="button secondary" onClick={()=>{setEditingSite(null);setSiteFormOpen(false);}}>Back to worksites</button></div><SiteForm key={editingSite?.id||'new-site'} initial={editingSite} busy={busy} onSubmit={saveSite}/></section>}
      </div>}
      {view==='breaks'&&<>
        <section className="panel break-history-panel">
          <div className="panel-head"><div><h2>Break and alert history</h2><p>Manual and AI-created safety actions.</p></div><div className="site-list-actions"><button className="button secondary" disabled={busy} onClick={schedule}>Ask AI to schedule</button><button className="button primary" onClick={openNewBreak}>Add safety log</button></div></div>
          {breaks.length?<div className="break-list">{breaks.map(item=><div className="break-item" key={item.id}><span className="break-icon">{item.alert_type==='storm'?'?':item.alert_type==='rain'?'?':item.alert_type==='earthquake'?'?':'?'}</span><div><strong>{item.title}</strong><small>{item.site} ? {item.break_date} ? {item.break_time} ? {item.duration_minutes} min</small>{item.ai_rationale&&<p>{item.ai_rationale}</p>}</div><Badge tone={item.source==='ai'?'ai':'neutral'}>{item.source==='ai'?'AI scheduled':item.status}</Badge>{item.source==='manual'&&<button className="tiny-action" onClick={()=>openBreakEditor(item)}>Edit</button>}</div>)}</div>:<Empty title="Nothing on the schedule" body="Add a safety log or use the weather assistant to suggest one." action="Add safety log" onClick={openNewBreak}/>}
        </section>
        {breakFormOpen&&<div className="worker-editor-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)setBreakFormOpen(false);}}><section className="worker-editor panel break-editor" role="dialog" aria-modal="true" aria-labelledby="break-editor-title"><div className="panel-head"><div><span className="kicker">{editingBreak?'UPDATE LOG':'NEW SAFETY LOG'}</span><h2 id="break-editor-title">{editingBreak?'Edit safety log':'Add a break or alert'}</h2><p>Choose the site and when this safety action applies.</p></div><button type="button" className="editor-close" aria-label="Close form" onClick={()=>setBreakFormOpen(false)}>?</button></div><form className="form-stack" onSubmit={createBreak}><label className="field">Action type<select name="alert_type" value={breakValues.alert_type} onChange={e=>setBreakValues({...breakValues,alert_type:e.target.value})}><option value="break">Water and shade break</option><option value="rain">Rain safety alert</option><option value="storm">Storm safety alert</option><option value="earthquake">Earthquake safety alert</option></select></label><label className="field">Worksite<select required name="site_id" value={breakValues.site_id} onChange={e=>setBreakValues({...breakValues,site_id:e.target.value})}><option value="">Choose a worksite</option>{sites.map(site=><option key={site.id} value={site.id}>{site.name}</option>)}</select></label>{!sites.length&&<p className="form-hint">Add a worksite before recording a safety log.</p>}<div className="form-two"><label className="field">Date<input required name="break_date" type="date" value={breakValues.break_date} onChange={e=>setBreakValues({...breakValues,break_date:e.target.value})}/></label><label className="field">Time<input required name="break_time" type="time" value={breakValues.break_time} onChange={e=>setBreakValues({...breakValues,break_time:e.target.value})}/></label></div><label className="field">Duration (minutes)<input required name="duration_minutes" type="number" min="1" max="240" value={breakValues.duration_minutes} onChange={e=>setBreakValues({...breakValues,duration_minutes:Number(e.target.value)})}/></label><label className="field">Status<select name="status" value={breakValues.status} onChange={e=>setBreakValues({...breakValues,status:e.target.value})}><option value="logged">Logged</option><option value="scheduled">Scheduled</option></select></label><div className="editor-actions"><button type="button" className="button secondary" onClick={()=>setBreakFormOpen(false)}>Cancel</button><button className="button primary" disabled={busy||!sites.length}>{busy?'Saving?':editingBreak?'Save changes':'Save safety log'}</button></div></form></section></div>}
      </>}
      {view==='alerts'&&<section className="panel"><div className="panel-head"><div><h2>Safety alerts</h2><p>Alert history from break and weather actions.</p></div><button className="button secondary" onClick={()=>setView('breaks')}>Create an alert</button></div><div className="simple-list">{breaks.filter(item=>item.alert_type!=='break').map(item=><div key={item.id}><span className="list-dot orange"/><div><strong>{item.title}</strong><small>{item.site} · {item.break_date} {item.break_time}</small></div><Badge tone="pending">{item.status}</Badge></div>)}</div></section>}
      {view==='reports'&&<section className="panel"><div className="panel-head"><div><h2>Organization snapshot</h2><p>Current worker, consent, and safety activity.</p></div><a className="button secondary" href="/api/privacy/export">Download data</a></div><div className="metric-grid"><Metric title="WORKERS" value={workers.length} sub="All registered workers"/><Metric title="CONSENTED" value={workers.filter(w=>w.consent_at).length} sub="Currently active consent"/><Metric title="SITES" value={sites.length} sub="Saved worksites"/><Metric title="SAFETY ACTIONS" value={breaks.length} sub="All recorded breaks and alerts"/></div></section>}
      <footer className="dash-footer"><span>JibonGuard · worker safety workspace</span><a href="/privacy.html">Privacy and data controls</a></footer>
    </div></main>
    {chatOpen&&<section className="chat-window"><header><div><strong>Ask JibonGuard AI</strong><small>Heat and workplace safety assistant</small></div><button onClick={()=>setChatOpen(false)} aria-label="Close chat">×</button></header><div className="chat-messages">{!chat.length&&<p className="chat-welcome">Hello! Ask about heat safety, your dashboard, or planning breaks.</p>}{chat.map((item,index)=><p key={index} className={item.role==='user'?'chat-user':'chat-assistant'}>{item.text}</p>)}</div><form onSubmit={sendChat}><textarea value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Ask a question…" rows="2"/><button className="button primary" disabled={busy||!prompt.trim()}>{busy?'…':'Send'}</button></form></section>}
    <button className="chat-launcher" onClick={()=>setChatOpen(value=>!value)}>{chatOpen?'Close assistant':'✳ Ask JibonGuard AI'}</button>
    </div>;
}

function Metric({title,value,sub,color='green'}) { return <article className={`metric metric-${color}`}><span>{title}</span><strong>{value}</strong><small>{sub}</small></article>; }
function Badge({children,tone='neutral'}) { return <span className={`badge ${tone}`}>{children}</span>; }
function Empty({title,body,action,onClick}) { return <div className="empty-state"><span>✳</span><strong>{title}</strong><p>{body}</p>{action&&<button className="button secondary" onClick={onClick}>{action}</button>}</div>; }
function SiteForm({initial,busy,onSubmit}) {
  const [query,setQuery]=useState(''),[results,setResults]=useState([]),[message,setMessage]=useState(''),[searching,setSearching]=useState(false);
  const [mapCoordinates,setMapCoordinates]=useState({latitude:initial?.latitude??'',longitude:initial?.longitude??''});
  const latitude=Number(mapCoordinates.latitude),longitude=Number(mapCoordinates.longitude);
  const hasCoordinates=String(mapCoordinates.latitude).trim()!==''&&String(mapCoordinates.longitude).trim()!==''&&Number.isFinite(latitude)&&Number.isFinite(longitude)&&latitude>=-90&&latitude<=90&&longitude>=-180&&longitude<=180;
  const mapLatitude=hasCoordinates?latitude:23.8103,mapLongitude=hasCoordinates?longitude:90.4125;
  const mapUrl=`https://www.openstreetmap.org/export/embed.html?bbox=${mapLongitude-0.01}%2C${mapLatitude-0.01}%2C${mapLongitude+0.01}%2C${mapLatitude+0.01}&layer=mapnik${hasCoordinates?`&marker=${latitude}%2C${longitude}`:''}`;
  async function search(){const term=query.trim();if(term.length<2){setResults([]);setMessage('Enter at least two characters to search.');return;}setSearching(true);setMessage('Searching places...');try{const result=await api(`/api/geocode/search?q=${encodeURIComponent(term)}`),found=Array.isArray(result.results)?result.results:[];setResults(found);setMessage(found.length?'Choose a result to fill the location.':'No locations found. Try a nearby city, district, or address.');}catch(error){setResults([]);setMessage(`${error.message} You can still set the map location with coordinates.`);}finally{setSearching(false);}}
  function selectResult(result){const form=document.getElementById('site-form');if(!form)return;form.elements.name.value=result.name||'';form.elements.address.value=result.display_name||'';form.elements.latitude.value=result.latitude;form.elements.longitude.value=result.longitude;setMapCoordinates({latitude:result.latitude,longitude:result.longitude});setResults([]);setMessage('Location added. Confirm the name and save.');}
  function chooseDhakaCenter(){const point={latitude:'23.8103',longitude:'90.4125'},form=document.getElementById('site-form');if(form){form.elements.latitude.value=point.latitude;form.elements.longitude.value=point.longitude;}setMapCoordinates(point);setMessage('Dhaka center selected. Adjust the coordinates if needed.');}
  return <form id="site-form" className="form-stack" onSubmit={onSubmit}><div className="place-search"><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();search();}}} placeholder="Search a city or address"/><button type="button" className="button secondary" disabled={searching} onClick={search}>{searching?'Searching…':'Search locations'}</button></div>{message&&<small className="form-hint" role="status">{message}</small>}{results.map((result,index)=><button key={`${result.latitude},${result.longitude},${index}`} type="button" className="place-result" onClick={()=>selectResult(result)}>{result.display_name}</button>)}<label className="field">Worksite name<input required name="name" defaultValue={initial?.name||''} maxLength="120"/></label><label className="field">Address<input name="address" defaultValue={initial?.address||''} maxLength="240"/></label><div className="form-two"><label className="field">Latitude<input required name="latitude" type="number" step="any" min="-90" max="90" defaultValue={initial?.latitude??''} onChange={e=>setMapCoordinates(v=>({...v,latitude:e.target.value}))}/></label><label className="field">Longitude<input required name="longitude" type="number" step="any" min="-180" max="180" defaultValue={initial?.longitude??''} onChange={e=>setMapCoordinates(v=>({...v,longitude:e.target.value}))}/></label></div><section className="site-map" aria-label="Worksite map preview"><div className="site-map-heading"><strong>Map preview</strong><a href={`https://www.openstreetmap.org/?mlat=${mapLatitude}&mlon=${mapLongitude}#map=15/${mapLatitude}/${mapLongitude}`} target="_blank" rel="noreferrer">Open larger map</a></div>{!hasCoordinates&&<button type="button" className="text-button map-center-action" onClick={chooseDhakaCenter}>Use Dhaka center</button>}<iframe title={hasCoordinates?'Map preview showing the selected worksite':'Map preview centered on Dhaka'} src={mapUrl} loading="eager" referrerPolicy="strict-origin-when-cross-origin"/><small>{hasCoordinates?'Map centered on the selected coordinates.':'Map is centered on Dhaka until you search or enter a location.'} Map data by OpenStreetMap contributors.</small></section><button className="button primary full" disabled={busy}>{busy?'Saving...':initial?'Save worksite':'Add worksite'}</button></form>;
}

function AccountPage() {
  const [user,setUser]=useState(null),[message,setMessage]=useState(''),[tone,setTone]=useState('error'),[busy,setBusy]=useState(false);
  useEffect(()=>{api('/api/auth/me').then(result=>setUser(result.user)).catch(()=>location.assign('/login.html?next=%2Faccount.html'));},[]);
  async function logout(){try{await post('/api/auth/logout',{});location.assign('/');}catch(error){setMessage(error.message);}}
  async function deleteAccount(event){event.preventDefault();if(!confirm('Permanently delete this organization and all its records?'))return;setBusy(true);try{const result=await post('/api/privacy/delete-account',{password:new FormData(event.currentTarget).get('password')});setTone('success');setMessage(result.message);setTimeout(()=>location.assign('/'),1200);}catch(error){setTone('error');setMessage(error.message);}finally{setBusy(false);}}
  return <><Header /><main className="account-page"><a className="back-link" href="/dashboard.html">← Back to dashboard</a><div className="page-heading"><span className="kicker">YOUR ACCOUNT CONTROLS</span><h1>Account and privacy</h1><p>Review your session, download a copy of your information, or delete the organization profile.</p></div><Message message={message} tone={tone}/><section className="account-card"><h2>Signed-in account</h2><p><strong>{user?.full_name||'Loading account…'}</strong><br/>{user?.email}<br/>Organization: {user?.organization_name}</p><button className="button secondary" onClick={logout}>Sign out</button></section><section className="account-card"><h2>Download your data</h2><p>Export your organization, worker, worksite, consent, and break records.</p><a className="button secondary" href="/api/privacy/export">↓ Download account data</a></section><section className="account-card danger-card"><h2>Delete the organization account</h2><p>Deletion permanently removes the organization profile, administrators, sessions, workers, worksites, consent history, and break logs.</p><form className="form-stack" onSubmit={deleteAccount}><label className="field">Current password<input required name="password" type="password" autoComplete="current-password" maxLength="128"/></label><button className="button danger-button" disabled={busy}>{busy?'Deleting…':'Permanently delete organization'}</button></form></section></main></>;
}

function PrivacyPage() {
  return <><Header/><main className="account-page"><a className="back-link" href="/">← Back to JibonGuard</a><div className="page-heading"><span className="kicker">PRIVACY AND TERMS</span><h1>Your trust matters</h1><p>JibonGuard is designed to help organizations coordinate heat-safety practices while respecting worker privacy.</p></div><section className="account-card"><h2>Information we store</h2><p>Organization account details, worksite information, worker records entered by administrators, consent events, and break or alert logs are stored to operate the workspace. Account passwords are protected with salted scrypt hashes. Session tokens are stored as hashes.</p></section><section className="account-card"><h2>Worker consent</h2><p>Worker alerts remain disabled until an administrator records that a worker received the privacy notice and explicitly agreed. Consent changes are recorded in an audit history. Administrators can withdraw consent.</p></section><section className="account-card"><h2>External services</h2><p>Weather lookups use Open-Meteo. Worksite place search uses Photon and OpenStreetMap Nominatim. AI answers are sent to Google Gemini when the organization configures an API key. SMS delivery uses TextBee when configured.</p></section><section className="account-card"><h2>Terms of use</h2><p>JibonGuard provides decision support and organizational records. Its sample risk guidance is illustrative and is not medical advice, emergency monitoring, or a substitute for official local warnings and workplace safety procedures.</p></section><p className="muted">Questions? <a href="mailto:hello@jibonguard.org">hello@jibonguard.org</a></p></main></>;
}

export default function App() {
  useEffect(()=>{const saved=localStorage.getItem(STORE);document.documentElement.dataset.theme=saved==='dark'?'dark':'light';},[]);
  const path=location.pathname;
  if(path==='/dashboard.html'||path==='/dashboard')return <Dashboard/>;
  if(path==='/account.html'||path==='/account')return <AccountPage/>;
  if(path==='/privacy.html'||path==='/privacy')return <PrivacyPage/>;
  if(path==='/signup.html'||path==='/signup')return <AuthPage mode="signup"/>;
  if(path==='/verify.html'||path==='/verify')return <AuthPage mode="verify"/>;
  if(path==='/resend-verification.html'||path==='/resend-verification')return <AuthPage mode="resend"/>;
  if(path==='/login.html'||path==='/login')return <AuthPage mode="login"/>;
  return <Home/>;
}

